/**
 * 澜景市地图世界书编辑器
 * 全屏 iframe 覆盖酒馆页面，以树状图形式编辑世界书条目
 */
import { teleportStyle } from '@util/script';
import App from './App.vue';
$(() => {
    const pinia = createPinia();
    const parentDoc = window.parent.document;
    let app = null;
    let iframeEl = null;
    let styleDestroy = null;
    function mountEditor() {
        if (app)
            return;
        /* 创建 iframe 并挂载到酒馆主页面 */
        const iframe = document.createElement('iframe');
        iframe.setAttribute('script_id', getScriptId());
        iframe.setAttribute('frameborder', '0');
        iframe.style.cssText =
            'position:fixed;top:0;left:0;width:100vw;height:100vh;z-index:99999;border:none;background:#080c18;';
        iframe.addEventListener('load', () => {
            const iframeDoc = iframe.contentDocument;
            if (!iframeDoc)
                return;
            /* 复制样式到 iframe head */
            const { destroy } = teleportStyle(iframeDoc.head);
            styleDestroy = destroy;
            /* 创建 Vue App 并挂载 */
            app = createApp(App, {
                onExit: unmountEditor,
            }).use(pinia);
            app.mount(iframeDoc.body);
        });
        parentDoc.body.appendChild(iframe);
        iframeEl = iframe;
    }
    function unmountEditor() {
        if (app) {
            app.unmount();
            app = null;
        }
        if (styleDestroy) {
            styleDestroy();
            styleDestroy = null;
        }
        if (iframeEl) {
            iframeEl.remove();
            iframeEl = null;
        }
    }
    /* 注册脚本按钮 */
    replaceScriptButtons([{ name: '打开地图编辑器', visible: true }]);
    eventOn(getButtonEvent('打开地图编辑器'), () => {
        mountEditor();
    });
    /* 关闭脚本时卸载 */
    $(window).on('pagehide', () => {
        unmountEditor();
    });
    console.info('[澜景市地图编辑器] 脚本已加载');
});
