CAEA,qDACE,iCACF,CAEA,4BACE,MACF,CAEA,gCACE,+BAAmC,CACnC,aACF,CAEA,sCACE,+BACF","sourcesContent":["<script setup lang=\"ts\">\nimport { useWorldbookStore } from '../stores/worldbook';\nimport { getLevelConfig, parseLocation } from '../utils/classifier';\n\nconst store = useWorldbookStore();\n\nconst node = computed(() => store.selectedNode);\nconst entry = computed(() => store.editingEntry);\nconst levelConfig = computed(() => (entry.value ? getLevelConfig(entry.value.position.order) : null));\nconst location = computed(() => (entry.value ? parseLocation(entry.value.content) : null));\nconst breadcrumb = computed(() => (node.value ? [...node.value.parentPath, node.value.name] : []));\n\nconst positionTypes: Array<{ value: WorldbookEntry['position']['type']; label: string }> = [\n  { value: 'before_character_definition', label: '角色定义之前' },\n  { value: 'after_character_definition', label: '角色定义之后' },\n  { value: 'before_example_messages', label: '示例消息之前' },\n  { value: 'after_example_messages', label: '示例消息之后' },\n  { value: 'before_author_note', label: '作者注释之前' },\n  { value: 'after_author_note', label: '作者注释之后' },\n  { value: 'at_depth', label: '聊天深度' },\n];\n\nfunction markDirty() {\n  if (!entry.value) return;\n  store.editingName = entry.value.name;\n  store.editingContent = entry.value.content;\n  store.dirty = true;\n}\n\nfunction parseKeys(value: string): string[] {\n  return value\n    .split(/\\r?\\n|,/)\n    .map(item => item.trim())\n    .filter(Boolean);\n}\n\nfunction stringifyKeys(keys: (string | RegExp)[]): string {\n  return keys.map(key => (key instanceof RegExp ? `/${key.source}/` : key)).join('\\n');\n}\n\nconst primaryKeysText = computed({\n  get: () => (entry.value ? stringifyKeys(entry.value.strategy.keys) : ''),\n  set: value => {\n    if (!entry.value) return;\n    entry.value.strategy.keys = parseKeys(value);\n    markDirty();\n  },\n});\n\nconst secondaryKeysText = computed({\n  get: () => (entry.value ? stringifyKeys(entry.value.strategy.keys_secondary.keys) : ''),\n  set: value => {\n    if (!entry.value) return;\n    entry.value.strategy.keys_secondary.keys = parseKeys(value);\n    markDirty();\n  },\n});\n\nconst scanDepthText = computed({\n  get: () => (entry.value ? String(entry.value.strategy.scan_depth) : 'same_as_global'),\n  set: value => {\n    if (!entry.value) return;\n    const trimmed = value.trim();\n    const parsed = Number(trimmed);\n    entry.value.strategy.scan_depth =\n      trimmed === '' || trimmed === 'same_as_global' || !Number.isFinite(parsed) ? 'same_as_global' : parsed;\n    markDirty();\n  },\n});\n\nfunction toNumber(value: string, fallback = 0): number {\n  const parsed = Number(value);\n  return Number.isFinite(parsed) ? parsed : fallback;\n}\n\nfunction toNullableNumber(value: string): number | null {\n  const trimmed = value.trim();\n  if (!trimmed) return null;\n  const parsed = Number(trimmed);\n  return Number.isFinite(parsed) ? parsed : null;\n}\n\nfunction nullableText(value: number | null): string {\n  return value == null ? '' : String(value);\n}\n\nfunction setName(value: string) {\n  if (!entry.value) return;\n  entry.value.name = value;\n  markDirty();\n}\n\nfunction setContent(value: string) {\n  if (!entry.value) return;\n  entry.value.content = value;\n  markDirty();\n}\n\nfunction setOrder(value: string) {\n  if (!entry.value) return;\n  const order = Math.min(5, Math.max(1, toNumber(value, entry.value.position.order)));\n  entry.value.position.order = order;\n  markDirty();\n}\n\nfunction setProbability(value: string) {\n  if (!entry.value) return;\n  entry.value.probability = Math.min(100, Math.max(0, toNumber(value, entry.value.probability)));\n  markDirty();\n}\n\nfunction setPositionDepth(value: string) {\n  if (!entry.value) return;\n  entry.value.position.depth = Math.max(0, toNumber(value, entry.value.position.depth));\n  markDirty();\n}\n\nfunction setEffectNumber(key: keyof WorldbookEntry['effect'], value: string) {\n  if (!entry.value) return;\n  entry.value.effect[key] = toNullableNumber(value);\n  markDirty();\n}\n\nfunction setRecursionDelay(value: string) {\n  if (!entry.value) return;\n  entry.value.recursion.delay_until = toNullableNumber(value);\n  markDirty();\n}\n\nfunction revert() {\n  if (!node.value) return;\n  store.editingEntry = _.cloneDeep(node.value.entry);\n  store.editingContent = node.value.entry.content;\n  store.editingName = node.value.name;\n  store.dirty = false;\n}\n\nasync function save() {\n  await store.saveCurrentEntry();\n}\n\nfunction onKeydown(e: KeyboardEvent) {\n  if ((e.ctrlKey || e.metaKey) && e.key === 's') {\n    e.preventDefault();\n    save();\n  }\n}\n</script>\n\n<template>\n  <div class=\"editor-panel\" @keydown=\"onKeydown\">\n    <div v-if=\"!node || !entry\" class=\"ep-empty\">\n      <div class=\"ep-empty-icon\">◆</div>\n      <div class=\"ep-empty-title\">选择条目</div>\n      <div class=\"ep-empty-hint\">点击图谱节点后在这里编辑世界书字段</div>\n    </div>\n\n    <template v-else>\n      <div class=\"ep-header\">\n        <div class=\"ep-breadcrumb\">\n          <span v-for=\"(part, i) in breadcrumb\" :key=\"i\" class=\"ep-crumb\">\n            <span v-if=\"i > 0\" class=\"ep-crumb-sep\">›</span>\n            <span :class=\"{ 'ep-crumb-current': i === breadcrumb.length - 1 }\">{{ part }}</span>\n          </span>\n        </div>\n        <div class=\"ep-meta\">\n          <span class=\"ep-badge\" :style=\"{ borderColor: levelConfig!.color + '60', color: levelConfig!.color }\">\n            {{ getLevelConfig(entry.position.order).icon }} L{{ entry.position.order }}\n            {{ getLevelConfig(entry.position.order).label }}\n          </span>\n          <span class=\"ep-badge\" :class=\"entry.enabled ? 'ep-badge-on' : 'ep-badge-off'\">\n            {{ entry.enabled ? '启用' : '禁用' }}\n          </span>\n          <span class=\"ep-badge ep-badge-uid\">UID {{ entry.uid }}</span>\n        </div>\n      </div>\n\n      <div class=\"ep-scroll\">\n        <section class=\"ep-section\">\n          <div class=\"ep-section-title\">基础</div>\n          <label class=\"ep-label\">条目名称</label>\n          <input class=\"ep-input ep-name-input\" :value=\"entry.name\" spellcheck=\"false\" @input=\"setName(($event.target as HTMLInputElement).value)\" />\n\n          <div class=\"ep-grid\">\n            <label class=\"ep-check\">\n              <input v-model=\"entry.enabled\" type=\"checkbox\" @change=\"markDirty\" />\n              <span>启用</span>\n            </label>\n\n            <label>\n              <span class=\"ep-label\">层级/order</span>\n              <select class=\"ep-input\" :value=\"entry.position.order\" @change=\"setOrder(($event.target as HTMLSelectElement).value)\">\n                <option v-for=\"l in [1, 2, 3, 4, 5]\" :key=\"l\" :value=\"l\">\n                  L{{ l }} {{ getLevelConfig(l).label }}\n                </option>\n              </select>\n            </label>\n\n            <label>\n              <span class=\"ep-label\">激活概率</span>\n              <input\n                class=\"ep-input\"\n                type=\"number\"\n                min=\"0\"\n                max=\"100\"\n                :value=\"entry.probability\"\n                @input=\"setProbability(($event.target as HTMLInputElement).value)\"\n              />\n            </label>\n          </div>\n        </section>\n\n        <section v-if=\"location && (location.district || location.street || location.place)\" class=\"ep-section ep-location-section\">\n          <div class=\"ep-section-title\">归属</div>\n          <div class=\"ep-location\">\n            <span v-if=\"location.district\" class=\"ep-loc-part\">{{ location.district }}</span>\n            <span v-if=\"location.street\" class=\"ep-loc-sep\">›</span>\n            <span v-if=\"location.street\" class=\"ep-loc-part\">{{ location.street }}</span>\n            <span v-if=\"location.place\" class=\"ep-loc-sep\">›</span>\n            <span v-if=\"location.place\" class=\"ep-loc-part\">{{ location.place }}</span>\n          </div>\n        </section>\n\n        <section class=\"ep-section\">\n          <div class=\"ep-section-title\">激活策略</div>\n          <div class=\"ep-grid\">\n            <label>\n              <span class=\"ep-label\">类型</span>\n              <select v-model=\"entry.strategy.type\" class=\"ep-input\" @change=\"markDirty\">\n                <option value=\"constant\">常量/蓝灯</option>\n                <option value=\"selective\">可选/绿灯</option>\n                <option value=\"vectorized\">向量化</option>\n              </select>\n            </label>\n\n            <label>\n              <span class=\"ep-label\">扫描深度</span>\n              <input v-model=\"scanDepthText\" class=\"ep-input\" spellcheck=\"false\" />\n            </label>\n\n            <label>\n              <span class=\"ep-label\">次要逻辑</span>\n              <select v-model=\"entry.strategy.keys_secondary.logic\" class=\"ep-input\" @change=\"markDirty\">\n                <option value=\"and_any\">与任意</option>\n                <option value=\"and_all\">与全部</option>\n                <option value=\"not_all\">非全部</option>\n                <option value=\"not_any\">非任意</option>\n              </select>\n            </label>\n          </div>\n\n          <label class=\"ep-label\">主要关键字</label>\n          <textarea v-model=\"primaryKeysText\" class=\"ep-small-textarea\" spellcheck=\"false\" />\n\n          <label class=\"ep-label\">次要关键字</label>\n          <textarea v-model=\"secondaryKeysText\" class=\"ep-small-textarea\" spellcheck=\"false\" />\n        </section>\n\n        <section class=\"ep-section\">\n          <div class=\"ep-section-title\">插入位置</div>\n          <div class=\"ep-grid\">\n            <label>\n              <span class=\"ep-label\">位置类型</span>\n              <select v-model=\"entry.position.type\" class=\"ep-input\" @change=\"markDirty\">\n                <option v-for=\"item in positionTypes\" :key=\"item.value\" :value=\"item.value\">{{ item.label }}</option>\n