import type { MapTreeNode } from './classifier';

export interface GraphLayoutNode {
  node: MapTreeNode;
  x: number;
  y: number;
  width: number;
  height: number;
  depth: number;
}

export interface GraphLayoutLink {
  from: GraphLayoutNode;
  to: GraphLayoutNode;
}

export interface GraphLayout {
  nodes: GraphLayoutNode[];
  links: GraphLayoutLink[];
  width: number;
  height: number;
}

interface MeasureNode {
  node: MapTreeNode;
  width: number;
  children: MeasureNode[];
}

const NODE_WIDTH: Record<number, number> = {
  1: 176,
  2: 142,
  3: 136,
  4: 116,
  5: 96,
};

const NODE_HEIGHT = 42;
const PADDING_X = 64;
const PADDING_Y = 48;
const LEVEL_GAP = 118;
const SIBLING_GAP = 18;

function getNodeWidth(node: MapTreeNode): number {
  return NODE_WIDTH[node.level] || NODE_WIDTH[4];
}

function measureNode(node: MapTreeNode, expandedSet: Set<number>): MeasureNode {
  const visibleChildren = expandedSet.has(node.entry.uid) ? node.children : [];
  const children = visibleChildren.map(child => measureNode(child, expandedSet));
  const childrenWidth =
    children.length === 0
      ? 0
      : children.reduce((sum, child) => sum + child.width, 0) + Math.max(0, children.length - 1) * SIBLING_GAP;
  const ownWidth = getNodeWidth(node);

  return {
    node,
    width: Math.max(ownWidth, childrenWidth),
    children,
  };
}

function placeNode(
  measured: MeasureNode,
  left: number,
  depth: number,
  nodes: GraphLayoutNode[],
  links: GraphLayoutLink[],
): GraphLayoutNode {
  const nodeWidth = getNodeWidth(measured.node);
  const layoutNode: GraphLayoutNode = {
    node: measured.node,
    x: left + measured.width / 2 - nodeWidth / 2,
    y: PADDING_Y + depth * LEVEL_GAP,
    width: nodeWidth,
    height: NODE_HEIGHT,
    depth,
  };
  nodes.push(layoutNode);

  if (measured.children.length > 0) {
    const childrenWidth =
      measured.children.reduce((sum, child) => sum + child.width, 0) +
      Math.max(0, measured.children.length - 1) * SIBLING_GAP;
    let childLeft = left + (measured.width - childrenWidth) / 2;

    for (const child of measured.children) {
      const childLayoutNode = placeNode(child, childLeft, depth + 1, nodes, links);
      links.push({ from: layoutNode, to: childLayoutNode });
      childLeft += child.width + SIBLING_GAP;
    }
  }

  return layoutNode;
}

export function buildGraphLayout(roots: MapTreeNode[], expandedSet: Set<number>): GraphLayout {
  const measuredRoots = roots.map(root => measureNode(root, expandedSet));
  const contentWidth =
    measuredRoots.length === 0
      ? 0
      : measuredRoots.reduce((sum, root) => sum + root.width, 0) + Math.max(0, measuredRoots.length - 1) * SIBLING_GAP;
  const nodes: GraphLayoutNode[] = [];
  const links: GraphLayoutLink[] = [];

  let left = PADDING_X;
  for (const measuredRoot of measuredRoots) {
    placeNode(measuredRoot, left, 0, nodes, links);
    left += measuredRoot.width + SIBLING_GAP;
  }

  const maxY = nodes.length === 0 ? 0 : Math.max(...nodes.map(node => node.y + node.height));

  return {
    nodes,
    links,
    width: Math.max(720, contentWidth + PADDING_X * 2),
    height: Math.max(360, maxY + PADDING_Y),
  };
}
