umber;\n  scrollLeft: number;\n  scrollTop: number;\n} | null>(null);\n\nconst MIN_ZOOM = 0.45;\nconst MAX_ZOOM = 1.55;\nconst ZOOM_STEP = 0.08;\n\nconst layout = computed(() => buildGraphLayout(store.filteredTree, store.expandedNodes));\n\nconst selectedUid = computed(() => store.selectedNode?.entry.uid ?? null);\nconst zoomLabel = computed(() => `${Math.round(zoom.value * 100)}%`);\n\nfunction countChildren(node: MapTreeNode): number {\n  let count = node.children.length;\n  for (const child of node.children) {\n    count += countChildren(child);\n  }\n  return count;\n}\n\nfunction truncate(text: string, max = 9): string {\n  if (text.length <= max) return text;\n  return `${text.slice(0, max - 1)}…`;\n}\n\nfunction linkPath(fromX: number, fromY: number, toX: number, toY: number): string {\n  const midY = (fromY + toY) / 2;\n  return `M ${fromX} ${fromY} C ${fromX} ${midY}, ${toX} ${midY}, ${toX} ${toY}`;\n}\n\nfunction clampZoom(value: number): number {\n  return Math.min(MAX_ZOOM, Math.max(MIN_ZOOM, value));\n}\n\nfunction setZoom(nextZoom: number, anchor?: { clientX: number; clientY: number }) {\n  const scroller = scrollRef.value;\n  const oldZoom = zoom.value;\n  const clamped = clampZoom(nextZoom);\n  if (Math.abs(clamped - oldZoom) < 0.001) return;\n\n  let localX = scroller ? scroller.clientWidth / 2 : 0;\n  let localY = scroller ? scroller.clientHeight / 2 : 0;\n  if (scroller && anchor) {\n    const rect = scroller.getBoundingClientRect();\n    localX = anchor.clientX - rect.left;\n    localY = anchor.clientY - rect.top;\n  }\n\n  const contentX = scroller ? (scroller.scrollLeft + localX) / oldZoom : 0;\n  const contentY = scroller ? (scroller.scrollTop + localY) / oldZoom : 0;\n  zoom.value = clamped;\n\n  if (scroller) {\n    nextTick(() => {\n      scroller.scrollLeft = Math.max(0, contentX * clamped - localX);\n      scroller.scrollTop = Math.max(0, contentY * clamped - localY);\n    });\n  }\n}\n\nfunction zoomIn() {\n  setZoom(zoom.value + ZOOM_STEP);\n}\n\nfunction zoomOut() {\n  setZoom(zoom.value - ZOOM_STEP);\n}\n\nfunction setZoomFromInput(e: Event) {\n  const value = Number((e.target as HTMLInputElement).value);\n  if (Number.isFinite(value)) setZoom(value);\n}\n\nfunction onWheel(e: WheelEvent) {\n  const target = e.target as Element | null;\n  if (target?.closest('input, textarea, select, button')) return;\n  e.preventDefault();\n\n  const direction = e.deltaY < 0 ? 1 : -1;\n  const strength = Math.min(3, Math.max(1, Math.abs(e.deltaY) / 120));\n  setZoom(zoom.value + direction * ZOOM_STEP * strength, { clientX: e.clientX, clientY: e.clientY });\n}\n\nfunction shouldIgnorePanTarget(target: EventTarget | null): boolean {\n  return target instanceof Element && Boolean(target.closest('.gp-node, input, textarea, select, button, a'));\n}\n\nfunction startPan(e: PointerEvent) {\n  if (e.button !== 0 && e.button !== 1) return;\n  if (shouldIgnorePanTarget(e.target)) return;\n\n  const scroller = scrollRef.value;\n  if (!scroller) return;\n\n  panState.value = {\n    pointerId: e.pointerId,\n    startX: e.clientX,\n    startY: e.clientY,\n    scrollLeft: scroller.scrollLeft,\n    scrollTop: scroller.scrollTop,\n  };\n  isPanning.value = true;\n  scroller.setPointerCapture(e.pointerId);\n  e.preventDefault();\n}\n\nfunction movePan(e: PointerEvent) {\n  const state = panState.value;\n  const scroller = scrollRef.value;\n  if (!state || !scroller || state.pointerId !== e.pointerId) return;\n\n  scroller.scrollLeft = state.scrollLeft - (e.clientX - state.startX);\n  scroller.scrollTop = state.scrollTop - (e.clientY - state.startY);\n  e.preventDefault();\n}\n\nfunction endPan(e: PointerEvent) {\n  const state = panState.value;\n  const scroller = scrollRef.value;\n  if (!state || state.pointerId !== e.pointerId) return;\n\n  if (scroller?.hasPointerCapture(e.pointerId)) {\n    scroller.releasePointerCapture(e.pointerId);\n  }\n  panState.value = null;\n  isPanning.value = false;\n}\n\nfunction selectNode(node: MapTreeNode) {\n  store.focusNode(node.entry.uid);\n}\n\nfunction toggleNode(node: MapTreeNode) {\n  if (node.children.length > 0) store.toggleExpand(node.entry.uid);\n}\n\nfunction walk(nodes: MapTreeNode[], visit: (node: MapTreeNode) => void) {\n  for (const node of nodes) {\n    visit(node);\n    walk(node.children, visit);\n  }\n}\n\nfunction expandAll() {\n  walk(store.tree, node => store.expandedNodes.add(node.entry.uid));\n}\n\nfunction collapseTo(level: number) {\n  store.expandedNodes.clear();\n  walk(store.tree, node => {\n    if (node.level < level) store.expandedNodes.add(node.entry.uid);\n  });\n}\n\nfunction centerOnUid(uid: number, behavior: ScrollBehavior = 'smooth') {\n  const scroller = scrollRef.value;\n  if (!scroller) return;\n  const item = layout.value.nodes.find(node => node.node.entry.uid === uid);\n  if (!item) return;\n\n  scroller.scrollTo({\n    left: Math.max(0, (item.x + item.width / 2) * zoom.value - scroller.clientWidth / 2),\n    top: Math.max(0, (item.y + item.height / 2) * zoom.value - scroller.clientHeight / 2),\n    behavior,\n  });\n}\n\nwatch(\n  () => store.graphFocusUid,\n  uid => {\n    if (uid == null) return;\n    nextTick(() => centerOnUid(uid));\n  },\n);\n\n</script>\n\n<template>\n  <div class=\"graph-panel\">\n    <div class=\"gp-toolbar\">\n      <div class=\"gp-search\">\n        <span class=\"gp-search-icon\">⌕</span>\n        <input v-model=\"store.searchQuery\" class=\"gp-search-input\" placeholder=\"搜索条目\" spellcheck=\"false\" />\n        <button v-if=\"store.searchQuery\" class=\"gp-icon-btn\" title=\"清空搜索\" @click=\"store.searchQuery = ''\">×</button>\n      </div>\n\n      <button class=\"gp-tool-btn\" title=\"展开全部\" @click=\"expandAll\">展开</button>\n      <button class=\"gp-tool-btn\" title=\"只展开到区\" @click=\"collapseTo(2)\">L2</button>\n      <button class=\"gp-tool-btn\" title=\"只展开到街道/片区\" @click=\"collapseTo(3)\">L3</button>\n      <button class=\"gp-tool-btn\" title=\"只展开到地点/设施\" @click=\"collapseTo(4)\">L4</button>\n\n      <div class=\"gp-zoom\">\n        <button class=\"gp-icon-btn\" title=\"缩小\" @click=\"zoomOut\">−</button>\n        <input :value=\"zoom\" class=\"gp-zoom-range\" type=\"range\" :min=\"MIN_ZOOM\" :max=\"MAX_ZOOM\" step=\"0.01\" @input=\"setZoomFromInput\" />\n        <span class=\"gp-zoom-label\">{{ zoomLabel }}</span>\n        <button class=\"gp-icon-btn\" title=\"放大\" @click=\"zoomIn\">＋</button>\n      </div>\n\n      <span class=\"gp-spacer\" />\n      <span class=\"gp-count\">{{ layout.nodes.length }} / {{ store.stats.total }}</span>\n      <span v-if=\"store.stats.unclassifiedCount > 0\" class=\"gp-warning\">未分类 {{ store.stats.unclassifiedCount }}</span>\n    </div>\n\n    <div\n      ref=\"scrollRef\"\n      class=\"gp-scroll\"\n      :class=\"{ panning: isPanning }\"\n      @wheel=\"onWheel\"\n      @pointerdown=\"startPan\"\n      @pointermove=\"movePan\"\n      @pointerup=\"endPan\"\n      @pointercancel=\"endPan\"\n      @lostpointercapture=\"endPan\"\n    >\n      <div v-if=\"layout.nodes.length === 0\" class=\"gp-empty\">没有可显示的条目</div>\n      <svg\n        v-else\n        class=\"gp-svg\"\n        :width=\"layout.width * zoom\"\n        :height=\"layout.height * zoom\"\n        :viewBox=\"`0 0 ${layout.width} ${layout.height}`\"\n      >\n        <defs>\n          <filter id=\"nodeShadow\" x=\"-20%\" y=\"-20%\" width=\"140%\" height=\"140%\">\n            <feDropShadow dx=\"0\" dy=\"8\" stdDeviation=\"8\" flood-color=\"#000000\" flood-opacity=\"0.25\" />\n          </filter>\n        </defs>\n\n        <path\n          v-for=\"link in layout.links\"\n          :key=\"`${link.from.node.entry.uid}-${link.to.node.entry.uid}`\"\n          class=\"gp-link\"\n          :d=\"linkPath(link.from.x + link.from.width / 2, link.from.y + link.from.height, link.to.x + link.to.width / 2, link.to.y)\"\n          :stroke=\"link.to.node.color\"\n        />\n\n        <g\n          v-for=\"item in layout.nodes\"\n          :key=\"item.node.entry.uid\"\n          class=\"gp-node\"\n          :class=\"{\n            selected: selectedUid === item.node.entry.uid,\n            disabled: !item.node.entry.enabled,\n            collapsed: item.node.children.length > 0 && !store.expandedNodes.has(item.node.entry.uid),\n          }\"\n          :transform=\"`translate(${item.x}, ${item.y})`\"\n          @click.stop=\"selectNode(item.node)\"\n          @dblclick.stop=\"toggleNode(item.node)\"\n        >\n          <rect\n            class=\"gp-node-bg\"\n            :width=\"item.width\"\n            :height=\"item.height\"\n            rx=\"7\"\n            :fill=\"item.node.entry.uid === selectedUid ? item.node.color : '#101729'\"\n            :stroke=\"item.node.color\"\n          />\n          <text class=\"gp-node-icon\" x=\"12\" y=\"17\" :fill=\"item.node.color\">{{ item.node.icon }}</text>\n          <text class=\"gp-node-title\" x=\"30\" y=\"18\" :title=\"item.node.name\">\n            {{ truncate(item.node.name, item.node.level <= 2 ? 12 : 10) }}\n          </text>\n          <text class=\"gp-node-meta\" x=\"30\" y=\"33\">\n            L{{ item.node.level }} {{ getLevelConfig(item.node.level).label }}\n          </text>\n          <g v-if=\"item.node.children.length > 0\" class=\"gp-node-count\" @click.stop=\"toggleNode(item.node)\">\n            <rect :x=\"item.width - 31\" y=\"25\" width=\"24\" height=\"12\" rx=\"6\" />\n            <text :x=\"item.width - 19\" y=\"34\" text-anchor=\"middle\">{{ countChildren(item.node) }}</text>\n          </g>\n        </g>\n      </svg>\n    </div>\n  </div>\n</template>\n\n<style scoped>\n.graph-panel {\n  display: flex;\n  flex-direction: column;\n  height: 100%;\n  min-width: 0;\n  overflow: hidden;\n  background: #0b1020;\n}\n\n.gp-toolbar {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  padding: 9px 12px;\n  border-bottom: 1px solid rgba(255, 255, 255, 0.07);\n  background: #0e1528;\n  flex-shrink: 0;\n}\n\n.gp-search {\n  display: flex;\n  align-items: center;\n  gap: 5px;\n  width: 240px;\n  min-width: 150px;\n  height: 30px;\n  padding: 0 8px;\n  border-radius: 6px;\n  border: 1px solid rgba(255, 255, 255, 0.08);\n  background: rgba(255, 255, 255, 0.04);\n  color: rgba(255, 255, 255, 0.42);\n}\n\n.gp-search-icon {\n  font-size: 13px;\n}\n\n.gp-search-input {\n  flex: 1;\n  min-width: 0;\n  border: none;\n  outline: none;\n  background: transparent;\n  color: rgba(255, 255, 255, 0.88);\n  font-size: 13px;\n}\n\n.gp-search-input::placeholder {\n  color: rgba(255, 255, 255, 0.3);\n}\n\n.gp-tool-btn,\n.gp-icon-btn {\n  height: 30px;\n  border: 1px solid rgba(255, 255, 255, 0.08);\n  background: rgba(255, 255, 255, 0.04);\n  color: rgba(255, 255, 255, 0.66);\n  cursor: pointer;\n  transition:\n    background 0.15s,\n    color 0.15s,\n    border-color 0.15s;\n}\n\n.gp-tool-btn {\n  padding: 0 10px;\n  border-radius: 6px;\n  font-size: 12px;\n  font-weight: 700;\n}\n\n.gp-icon-btn {\n  width: 30px;\n  border-radius: 6px;\n  font-size: 15px;\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n}\n\n.gp-tool-btn:hover,\n.gp-icon-btn:hover {\n  background: rgba(96, 165, 250, 0.12);\n  border-color: rgba(96, 165, 250, 0.35);\n  color: rgba(255, 255, 255, 0.9);\n}\n\n.gp-zoom {\n  display: flex;\n  align-items: center;\n  gap: 5px;\n}\n\n.gp-zoom-range {\n  width: 96px;\n  accent-color: #60a5fa;\n}\n\n.gp-zoom-label {\n  width: 38px;\n  color: rgba(255, 255, 255, 0.42);\n  font-size: 11px;\n  font-weight: 800;\n  text-align: center;\n  font-variant-numeric: tabular-nums;\n}\n\n.gp-spacer {\n  flex: 1;\n}\n\n.gp-count,\n.gp-warning {\n  font-size: 12px;\n  color: rgba(255, 255, 255, 0.42);\n  white-space: nowrap;\n}\n\n.gp-warning {\n  color: #fbbf24;\n}\n\n.gp-scroll {\n  flex: 1;\n  overflow: auto;\n  min-height: 0;\n  cursor: grab;\n  user-select: none;\n  touch-action: none;\n  background:\n    linear-gradient(rgba(255, 255, 255, 0.025) 1px, transparent 1px),\n    linear-gradient(90deg, rgba(255, 255, 255, 0.025) 1px, transparent 1px),\n    #0b1020;\n  background-size: 32px 32px;\n}\n\n.gp-scroll.panning {\n  cursor: grabbing;\n}\n\n.gp-scroll::-webkit-scrollbar {\n  width: 8px;\n  height: 8px;\n}\n\n.gp-scroll::-webkit-scrollbar-thumb {\n  border-radius: 4px;\n  background: rgba(255, 255, 255, 0.14);\n}\n\n.gp-svg {\n  display: block;\n}\n\n.gp-link {\n  fill: none;\n  stroke-width: 1.4;\n  stroke-opacity: 0.32;\n}\n\n.gp-node {\n  cursor: pointer;\n}\n\n.gp-node-bg {\n  filter: url(#nodeShadow);\n  stroke-width: 1.2;\n  stroke-opacity: 0.6;\n}\n\n.gp-node.selected .gp-node-bg {\n  stroke: rgba(255, 255, 255, 0.9);\n  stroke-width: 2;\n}\n\n.gp-node.disabled {\n  opacity: 0.45;\n}\n\n.gp-node.collapsed .gp-node-bg {\n  stroke-dasharray: 4 3;\n}\n\n.gp-node-title {\n  fill: rgba(255, 255, 255, 0.88);\n  font-size: 12px;\n  font-weight: 700;\n}\n\n.gp-node.selected .gp-node-title,\n.gp-node.selected .gp-node-meta,\n.gp-node.selected .gp-node-icon {\n  fill: #ffffff;\n}\n\n.gp-node-meta {\n  fill: rgba(255, 255, 255, 0.45);\n  font-size: 10px;\n}\n\n.gp-node-icon {\n  font-size: 12px;\n  font-weight: 800;\n}\n\n.gp-node-count rect {\n  fill: rgba(255, 255, 255, 0.08);\n  stroke: rgba(255, 255, 255, 0.1);\n}\n\n.gp-node-count text {\n  fill: rgba(255, 255, 255, 0.62);\n  font-size: 8px;\n  font-weight: 800;\n}\n\n.gp-empty {\n  padding: 34px;\n  color: rgba(255, 255, 255, 0.36);\n  font-size: 13px;\n}\n</style>\n"],"sourceRoot":""}]);
