/**
 * 世界书数据层 - 负责与酒馆世界书 API 交互
 */
import { classifyEntries, extractDisplayName, updateLocationInContent, determineLevel } from '../utils/classifier';
const WORLDBOOK_NAME = '澜景市';
export const useWorldbookStore = defineStore('mapEditor-worldbook', () => {
    /** 原始条目列表 */
    const entries = ref([]);
    /** 树状结构 */
    const tree = ref([]);
    /** 未分类条目 */
    const unclassified = ref([]);
    /** 加载中 */
    const loading = ref(false);
    /** 展开状态（uid 集合） */
    const expandedNodes = ref(new Set());
    /** 当前选中的节点 */
    const selectedNode = ref(null);
    /** 搜索关键词 */
    const searchQuery = ref('');
    /** 层级筛选 */
    const levelFilter = ref(new Set([1, 2, 3, 4, 5]));
    /** 是否有未保存的修改 */
    const dirty = ref(false);
    /** 编辑中的完整条目副本 */
    const editingEntry = ref(null);
    /** 编辑中的条目内容 */
    const editingContent = ref('');
    /** 编辑中的条目名称 */
    const editingName = ref('');
    /** 图谱聚焦请求 */
    const graphFocusUid = ref(null);
    /** 加载世界书数据 */
    async function loadWorldbook() {
        loading.value = true;
        try {
            const rawEntries = await getWorldbook(WORLDBOOK_NAME);
            entries.value = rawEntries;
            rebuildTree();
            // 首次加载时展开到区级，默认呈现 1 -> 2 -> 3 的地图骨架；地点和详情可继续展开。
            if (expandedNodes.value.size === 0) {
                for (const entry of rawEntries) {
                    if (determineLevel(entry) <= 2) {
                        expandedNodes.value.add(entry.uid);
                    }
                }
            }
            console.info(`[地图编辑器] 已加载 ${rawEntries.length} 个条目`);
        }
        catch (e) {
            console.error('[地图编辑器] 加载世界书失败:', e);
            toastr.error(`加载世界书"${WORLDBOOK_NAME}"失败: ${e}`);
        }
        finally {
            loading.value = false;
        }
    }
    /** 重建树状结构 */
    function rebuildTree() {
        const result = classifyEntries(entries.value);
        tree.value = result.tree;
        unclassified.value = result.unclassified;
    }
    function setEditingFromNode(node) {
        selectedNode.value = node;
        dirty.value = false;
        if (node) {
            editingContent.value = node.entry.content;
            editingName.value = node.name;
            editingEntry.value = _.cloneDeep(node.entry);
        }
        else {
            editingContent.value = '';
            editingName.value = '';
            editingEntry.value = null;
        }
    }
    function findNodePathByUid(nodes, uid, path = []) {
        for (const node of nodes) {
            const nextPath = [...path, node];
            if (node.entry.uid === uid)
                return nextPath;
            const found = findNodePathByUid(node.children, uid, nextPath);
            if (found)
                return found;
        }
        return null;
    }
    function requestGraphFocus(uid) {
        graphFocusUid.value = null;
        nextTick(() => {
            graphFocusUid.value = uid;
        });
    }
    function refreshSelectionAfterClassify(uid, focusGraph = false) {
        const treePath = findNodePathByUid(tree.value, uid);
        const path = treePath || findNodePathByUid(unclassified.value, uid);
        if (!path)
            return false;
        if (treePath) {
            for (const ancestor of treePath.slice(0, -1)) {
                expandedNodes.value.add(ancestor.entry.uid);
            }
        }
        setEditingFromNode(path[path.length - 1]);
        if (focusGraph)
            requestGraphFocus(uid);
        return true;
    }
    /** 选中一个节点 */
    function selectNode(node) {
        if (dirty.value && selectedNode.value) {
            if (!confirm('有未保存的修改，确定要切换吗？'))
                return false;
        }
        setEditingFromNode(node);
        return true;
    }
    /** 保存当前编辑中的条目 */
    async function saveCurrentEntry() {
        if (!selectedNode.value)
            return;
        const node = selectedNode.value;
        const uid = node.entry.uid;
        const nextEntry = editingEntry.value ? _.cloneDeep(editingEntry.value) : _.cloneDeep(node.entry);
        nextEntry.uid = uid;
        nextEntry.name = editingName.value;
        nextEntry.content = editingContent.value;
        try {
            loading.value = true;
            // 更新条目
            await updateWorldbookWith(WORLDBOOK_NAME, worldbook => {
                return worldbook.map(entry => {
                    if (entry.uid === uid) {
                        return {
                            ...entry,
                            ...nextEntry,
                        };
                    }
                    return entry;
                });
            });
            dirty.value = false;
            toastr.success(`已保存: ${editingName.value}`);
            // 重新加载并重建树
            await loadWorldbook();
            // 重新选中同一个条目，展开新的父级路径并通知图谱滚到更新后的分类位置。
            refreshSelectionAfterClassify(uid, true);
        }
        catch (e) {
            console.error('[地图编辑器] 保存失败:', e);
            toastr.error(`保存失败: ${e}`);
        }
        finally {
            loading.value = false;
        }
    }
    /** 修改条目的 order（层级） */
    async function changeEntryOrder(uid, newOrder) {
        try {
            await updateWorldbookWith(WORLDBOOK_NAME, worldbook => {
                return worldbook.map(entry => {
                    if (entry.uid === uid) {
                        return {
                            ...entry,
                            position: { ...entry.position, order: newOrder },
                        };
                    }
                    return entry;
                });
            });
            await loadWorldbook();
            refreshSelectionAfterClassify(uid, true);
            toastr.success('层级已更新');
        }
        catch (e) {
            toastr.error(`修改层级失败: ${e}`);
        }
    }
    /** 移动条目到新的父节点下（修改位置字段） */
    async function moveEntry(uid, targetParent) {
        try {
            const entry = entries.value.find(e => e.uid === uid);
            if (!entry)
                return;
            const newLocation = buildLocationFromParent(targetParent);
            const newContent = updateLocationInContent(entry.content, newLocation);
            await updateWorldbookWith(WORLDBOOK_NAME, worldbook => {
                return worldbook.map(e => {
                    if (e.uid === uid) {
                        return { ...e, content: newContent };
                    }
                    return e;
                });
            });
            await loadWorldbook();
            refreshSelectionAfterClassify(uid, true);
            toastr.success(`已移动到: ${targetParent.name}`);
        }
        catch (e) {
            toastr.error(`移动失败: ${e}`);
        }
    }
    /** 新建条目 */
    async function createEntry(name, parentNode, level) {
        try {
            const content = buildNewEntryContent(name, parentNode, level);
            await createWorldbookEntries(WORLDBOOK_NAME, [{
                    name,
                    content,
                    enabled: true,
                    position: { order: level, type: 'before_character_definition', role: 'system', depth: 0 },
                    strategy: { type: 'selective', keys: [name], keys_secondary: { logic: 'and_any', keys: [] }, scan_depth: 'same_as_global' },
                }]);
            await loadWorldbook();
            toastr.success(`已创建: ${name}`);
        }
        catch (e) {
            toastr.error(`创建失败: ${e}`);
        }
    }
    /** 删除条目 */
    async function deleteEntry(uid) {
        const entry = entries.value.find(e => e.uid === uid);
        if (!entry)
            return;
        if (!confirm(`确定要删除条目"${extractDisplayName(entry)}"吗？此操作不可撤销。`))
            return;
        try {
            await deleteWorldbookEntries(WORLDBOOK_NAME, e => e.uid === uid);
            if (selectedNode.value?.entry.uid === uid) {
                selectedNode.value = null;
                editingContent.value = '';
                editingName.value = '';
                editingEntry.value = null;
            }
            await loadWorldbook();
            toastr.success(`已删除: ${extractDisplayName(entry)}`);
        }
        catch (e) {
            toastr.error(`删除失败: ${e}`);
        }
    }
    /** 切换条目启用/禁用 */
    async function toggleEnabled(uid) {
        try {
            const entry = entries.value.find(e => e.uid === uid);
            if (!entry)
                return;
            await updateWorldbookWith(WORLDBOOK_NAME, worldbook => {
                return worldbook.map(e => {
                    if (e.uid === uid) {
                        return { ...e, enabled: !e.enabled };
                    }
                    return e;
                });
            });
            await loadWorldbook();
        }
        catch (e) {
            toastr.error(`切换失败: ${e}`);
        }
    }
    /** 在树中查找指定 uid 的节点 */
    function findNodeByUid(nodes, uid) {
        for (const node of nodes) {
            if (node.entry.uid === uid)
                return node;
            const found = findNodeByUid(node.children, uid);
            if (found)
                return found;
        }
        return null;
    }
    function focusNode(uid) {
        const treePath = findNodePathByUid(tree.value, uid);
        if (treePath) {
            for (const ancestor of treePath.slice(0, -1)) {
                expandedNodes.value.add(ancestor.entry.uid);
            }
            if (selectNode(treePath[treePath.length - 1]))
                requestGraphFocus(uid);
            return;
        }
        const node = findNodeByUid(unclassified.value, uid);
        if (node && selectNode(node))
            requestGraphFocus(uid);
    }
    /** 过滤后的树（搜索 + 层级筛选） */
    const filteredTree = computed(() => {
        let result = tree.value;
        if (searchQuery.value.trim()) {
            result = filterBySearch(result, searchQuery.value.toLowerCase());
        }
        return result;
    });
    function filterBySearch(nodes, query) {
        const result = [];
        for (const node of nodes) {
            const nameMatch = node.name.toLowerCase().includes(query);
            const contentMatch = node.entry.content.toLowerCase().includes(query);
            const filteredChildren = filterBySearch(node.children, query);
            if (nameMatch || contentMatch || filteredChildren.length > 0) {
                // 搜索时自动展开匹配路径
                if (nameMatch || contentMatch || filteredChildren.length > 0) {
                    expandedNodes.value.add(node.entry.uid);
                }
                result.push({
                    ...node,
                    children: filteredChildren.length > 0 ? filteredChildren : node.children,
                });
            }
        }
        return result;
    }
    /** 切换展开/折叠 */
    function toggleExpand(uid) {
        if (expandedNodes.value.has(uid)) {
            expandedNodes.value.delete(uid);
        }
        else {
            expandedNodes.value.add(uid);
        }
    }
    function buildLocationFromParent(parentNode) {
        const fullPath = [...parentNode.parentPath, parentNode.name];
        const district = fullPath.find(part => part.endsWith('区'));
        const street = fullPath.find(part => /(街道|片区|景区)$/.test(part));
        const result = {};
        if (district)
            result.district = district;
        if (street)
            result.street = street;
        if (parentNode.level >= 4)
            result.place = parentNode.name;
        return result;
    }
    function buildNewEntryContent(name, parentNode, level) {
        if (!parentNode || level <= 2) {
            return `<${name}>\n${name}:\n  定位: \n</${name}>`;
        }
        if (level === 3) {
            const district = parentNode.level === 2 ? parentNode.name : buildLocationFromParent(parentNode).district;
            return `<${name}>\n${name}:\n  所属: ${district ?? ''}\n  定位: \n</${name}>`;
        }
        const location = buildLocationFromParent(parentNode);
        const locationStr = [location.district, location.street, location.place].filter(Boolean).join('·');
        return `<${name}>\n${name}:\n  位置: ${locationStr ? `${locationStr}·` : ''}\n  类型: \n</${name}>`;
    }
    /** 检查是否展开 */
    function isExpanded(uid) {
        return expandedNodes.value.has(uid);
    }
    /** 统计信息 */
    const stats = computed(() => {
        const total = entries.value.length;
        const byLevel = _.countBy(entries.value, e => determineLevel(e));
        return {
            total,
            l1: byLevel[1] || 0,
            l2: byLevel[2] || 0,
            l3: byLevel[3] || 0,
            l4: byLevel[4] || 0,
            l5: byLevel[5] || 0,
            unclassifiedCount: unclassified.value.length,
        };
    });
    return {
        entries,
        tree,
        unclassified,
        loading,
        expandedNodes,
        selectedNode,
        searchQuery,
        levelFilter,
        dirty,
        editingEntry,
        editingContent,
        editingName,
        graphFocusUid,
        filteredTree,
        stats,
        loadWorldbook,
        rebuildTree,
        selectNode,
        toggleExpand,
        isExpanded,
        focusNode,
        saveCurrentEntry,
        changeEntryOrder,
        moveEntry,
        createEntry,
        deleteEntry,
        toggleEnabled,
        findNodeByUid,
    };
});
