/**
 * 世界书条目自动分类引擎
 *
 * 澜景市当前世界书的 order 对应关系：
 * L1 城市级总览/体系，L2 区，L3 街道/片区/景区，L4 地点/设施，L5 详情。
 */
/** 层级配置 */
const LEVEL_CONFIG = {
    1: { icon: '◆', color: '#60a5fa', label: '城市级' },
    2: { icon: '⬡', color: '#34d399', label: '区' },
    3: { icon: '▣', color: '#f59e0b', label: '街道/片区' },
    4: { icon: '●', color: '#f472b6', label: '地点/设施' },
    5: { icon: '•', color: '#a78bfa', label: '详情' },
};
const AREA_SUFFIX_RE = /(区|街道|片区|景区)$/;
const WRAPPED_NOTE_RE = /[（(].*?[）)]/g;
export function getLevelConfig(level) {
    return LEVEL_CONFIG[level] || LEVEL_CONFIG[4];
}
/**
 * 从条目 name 中提取显示名
 * 世界书条目的 name 通常就是 XML 标签名，如 "听涛区"、"北山街道"
 */
export function extractDisplayName(entry) {
    if (entry.name && entry.name.trim()) {
        return entry.name.trim();
    }
    const xmlMatch = entry.content.match(/^<([^>]+)>/);
    if (xmlMatch) {
        return xmlMatch[1].trim();
    }
    return `条目#${entry.uid}`;
}
/**
 * 从条目 order 确定层级
 */
export function determineLevel(entry) {
    const order = entry.position.order;
    if (order >= 1 && order <= 5)
        return order;
    const name = extractDisplayName(entry);
    if (name.includes('澜景市') && /总览|体系|地理/.test(name))
        return 1;
    if (name.endsWith('区'))
        return 2;
    if (name.endsWith('街道') || name.endsWith('片区') || name.endsWith('景区'))
        return 3;
    if (name.includes('详情'))
        return 5;
    return 4;
}
function normalizeRef(value) {
    return value
        .replace(/^<|>$/g, '')
        .replace(WRAPPED_NOTE_RE, '')
        .replace(/[，,；;。].*$/g, '')
        .replace(/\s+/g, '')
        .trim();
}
function cleanPathPart(value) {
    return normalizeRef(value)
        .replace(/^(位于|在|至|到)/, '')
        .replace(/方向$/, '')
        .trim();
}
function splitHierarchy(raw, allowSingle) {
    const cleaned = raw.trim();
    const hasSeparator = /[·>＞/\\]/.test(cleaned);
    if (!hasSeparator && !allowSingle)
        return [];
    const parts = cleaned
        .split(/[·>＞/\\]/)
        .map(cleanPathPart)
        .filter(Boolean);
    if (parts.length === 0 && allowSingle) {
        const single = cleanPathPart(cleaned);
        return single ? [single] : [];
    }
    return parts;
}
function matchField(content, fields) {
    const fieldPattern = fields.join('|');
    const re = new RegExp(`^\\s*(?:${fieldPattern})\\s*[:：]\\s*([^\\n\\r]+)`, 'm');
    return content.match(re)?.[1]?.trim();
}
/**
 * 解析条目内容中的归属信息。
 * 支持：
 * - 所属: 映湖区
 * - 所属: 映湖区（独立片区，不属于任何街道）
 * - 位置: 映湖区·北山街道·北山路沿线
 * - 位置: 映湖区·南屏路街道·澜景市附属中学·操场东南角
 */
export function parseLocation(content) {
    const positionRaw = matchField(content, ['位置', '地点', '地址']);
    const belongRaw = matchField(content, ['所属', '归属', '隶属', '所属区', '所属区域']);
    const fromPosition = positionRaw ? splitHierarchy(positionRaw, false) : [];
    const fromBelong = belongRaw ? splitHierarchy(belongRaw, true) : [];
    const parts = fromPosition.length > 0 ? fromPosition : fromBelong;
    const raw = fromPosition.length > 0 ? positionRaw : belongRaw;
    const source = fromPosition.length > 0 ? '位置' : belongRaw ? '所属' : undefined;
    const result = {
        parts,
        raw,
        source,
    };
    if (parts.length >= 1 && (AREA_SUFFIX_RE.test(parts[0]) || source === '所属')) {
        result.district = parts[0];
    }
    if (parts.length >= 2)
        result.street = parts[1];
    if (parts.length >= 3)
        result.place = parts[2];
    if (parts.length >= 4)
        result.detail = parts[3];
    return result;
}
function keyToString(key) {
    return key instanceof RegExp ? key.source : key;
}
function getEntryReferences(entry) {
    return [
        ...entry.strategy.keys.map(keyToString),
        ...entry.strategy.keys_secondary.keys.map(keyToString),
    ].filter(Boolean);
}
function getNodeAliases(node) {
    const aliases = new Set();
    const add = (value) => {
        if (!value)
            return;
        const normalized = normalizeRef(value);
        if (normalized.length > 0)
            aliases.add(normalized);
    };
    add(node.name);
    add(node.name.replace(/区$/, ''));
    add(node.name.replace(/街道$/, ''));
    add(node.name.replace(/片区$/, ''));
    add(node.name.replace(/景区$/, ''));
    add(node.name.replace(/^澜景市/, ''));
    add(node.name.replace(/^澜景/, ''));
    for (const ref of getEntryReferences(node.entry)) {
        add(ref);
    }
    return [...aliases];
}
function referenceMatchesNode(ref, node) {
    const normalized = normalizeRef(ref);
    if (!normalized)
        return false;
    return getNodeAliases(node).includes(normalized);
}
function findBestByReference(ref, candidates) {
    if (!ref)
        return null;
    const matches = candidates.filter(candidate => referenceMatchesNode(ref, candidate));
    if (matches.length === 0)
        return null;
    return _.maxBy(matches, candidate => candidate.name.length) ?? null;
}
function findBestByReferences(refs, candidates) {
    for (const ref of refs) {
        const found = findBestByReference(ref, candidates);
        if (found)
            return found;
    }
    return null;
}
function entryHeadingText(entry) {
    return entry.content.split(/\r?\n/).slice(0, 6).join('\n');
}
function findMentionedParent(node, candidates) {
    const heading = entryHeadingText(node.entry);
    const matches = candidates.filter(candidate => {
        if (candidate.entry.uid === node.entry.uid)
            return false;
        if (heading.includes(candidate.name))
            return true;
        return getNodeAliases(candidate).some(alias => alias.length >= 3 && heading.includes(alias));
    });
    if (matches.length === 0)
        return null;
    return _.maxBy(matches, candidate => candidate.name.length) ?? null;
}
/**
 * 从详情条目名称推断其父条目名称
 * "保俶路便利店店内详情" → "保俶路便利店"
 * "中山公园园内详情" → "中山公园"
 */
export function inferParentFromDetailName(name) {
    const suffixes = [
        '店内详情',
        '园内详情',
        '园区详情',
        '站内详情',
        '网点详情',
        '站点详情',
        '住宿详情',
        '停车详情',
        '楼层详情',
        '校内详情',
        '影城详情',
        '项目详情',
        '设施详情',
        '详情',
    ].sort((a, b) => b.length - a.length);
    for (const suffix of suffixes) {
        if (name.endsWith(suffix)) {
            const base = name.slice(0, -suffix.length).replace(/[·-]$/, '');
            return base || null;
        }
    }
    return null;
}
function attachNode(parent, child) {
    if (parent.entry.uid === child.entry.uid)
        return false;
    if (child.parentPath.length > 0)
        return false;
    child.parentPath = [...parent.parentPath, parent.name];
    parent.children.push(child);
    return true;
}
function findParentFromLocation(node, byLevel) {
    const location = parseLocation(node.entry.content);
    const refs = location.parts;
    if (node.level === 2) {
        return null;
    }
    if (node.level === 3) {
        return findBestByReferences(refs, byLevel[2] || []);
    }
    if (node.level === 4) {
        return (findBestByReference(refs[1], byLevel[3] || []) ||
            findBestByReference(refs[0], byLevel[2] || []) ||
            null);
    }
    return (findBestByReference(refs[2], byLevel[4] || []) ||
        findBestByReference(refs[1], byLevel[3] || []) ||
        findBestByReference(refs[0], byLevel[2] || []) ||
        null);
}
function findParentFromKeys(node, byLevel) {
    const refs = getEntryReferences(node.entry);
    if (node.level === 3) {
        return findBestByReferences(refs, byLevel[2] || []);
    }
    if (node.level === 4) {
        return findBestByReferences(refs, byLevel[3] || []) || findBestByReferences(refs, byLevel[2] || []);
    }
    if (node.level === 5) {
        return (findBestByReferences(refs, byLevel[4] || []) ||
            findBestByReferences(refs, byLevel[3] || []) ||
            findBestByReferences(refs, byLevel[2] || []));
    }
    return null;
}
function findDetailParent(node, byLevel) {
    if (node.level !== 5)
        return null;
    const l4Nodes = byLevel[4] || [];
    const inferred = inferParentFromDetailName(node.name);
    return findBestByReference(inferred ?? undefined, l4Nodes) || findMentionedParent(node, l4Nodes);
}
function findCityOverviewRoot(l1Nodes) {
    return (l1Nodes.find(node => node.name === '澜景市城市总览') ||
        l1Nodes.find(node => node.name.includes('城市总览')) ||
        l1Nodes[0] ||
        null);
}
/**
 * 将世界书条目列表构建为树状结构
 */
export function classifyEntries(entries) {
    const nodes = entries.map(entry => {
        const level = determineLevel(entry);
        const config = getLevelConfig(level);
        return {
            entry,
            level,
            name: extractDisplayName(entry),
            parentPath: [],
            children: [],
            icon: config.icon,
            color: config.color,
        };
    });
    const byLevel = _.groupBy(nodes, 'level');
    const l1Nodes = byLevel[1] || [];
    const cityOverview = findCityOverviewRoot(l1Nodes);
    // L2 区统一挂到城市总览下；这和世界书中“六区”段落一致。
    for (const node of byLevel[2] || []) {
        const explicitParent = findBestByReferences(parseLocation(node.entry.content).parts, l1Nodes) || findMentionedParent(node, l1Nodes);
        const parent = explicitParent || cityOverview;
        if (parent)
            attachNode(parent, node);
    }
    for (const level of [3, 4, 5]) {
        for (const node of byLevel[level] || []) {
            const parent = findDetailParent(node, byLevel) ||
                findParentFromLocation(node, byLevel) ||
                findParentFromKeys(node, byLevel) ||
                findMentionedParent(node, nodes.filter(candidate => candidate.level < node.level));
            if (parent)
                attachNode(parent, node);
        }
    }
    const classified = new Set();
    function markClassified(node) {
        classified.add(node);
        for (const child of node.children) {
            markClassified(child);
        }
    }
    for (const root of l1Nodes) {
        markClassified(root);
    }
    const unclassified = nodes.filter(node => !classified.has(node));
    function sortChildren(node) {
        node.children.sort((a, b) => {
            if (a.level !== b.level)
                return a.level - b.level;
            return a.entry.uid - b.entry.uid;
        });
        for (const child of node.children) {
            sortChildren(child);
        }
    }
    for (const root of l1Nodes) {
        sortChildren(root);
    }
    return {
        tree: [...l1Nodes].sort((a, b) => a.entry.uid - b.entry.uid),
        unclassified,
    };
}
/**
 * 修改条目内容中的位置/所属字段
 */
export function updateLocationInContent(content, newLocation) {
    const locationStr = [newLocation.district, newLocation.street, newLocation.place, newLocation.detail]
        .filter(Boolean)
        .join('·');
    if (!locationStr)
        return content;
    if (/^\s*位置\s*[:：]\s*[^\n\r]*/m.test(content)) {
        return content.replace(/^(\s*)位置\s*[:：]\s*[^\n\r]*/m, `$1位置: ${locationStr}·`);
    }
    if (/^\s*所属\s*[:：]\s*[^\n\r]*/m.test(content)) {
        return content.replace(/^(\s*)所属\s*[:：]\s*[^\n\r]*/m, `$1所属: ${locationStr}`);
    }
    const lines = content.split('\n');
    if (lines.length >= 2) {
        lines.splice(2, 0, `  位置: ${locationStr}·`);
        return lines.join('\n');
    }
    return content;
}
/**
 * 重新分类单个条目，返回它应该归属的父节点路径
 */
export function reclassifyEntry(entry, allEntries) {
    const { tree } = classifyEntries(allEntries);
    const name = extractDisplayName(entry);
    function findNode(nodes) {
        for (const node of nodes) {
            if (node.name === name)
                return node;
            const found = findNode(node.children);
            if (found)
                return found;
        }
        return null;
    }
    const found = findNode(tree);
    return found ? found.parentPath : [];
}
/**
 * 扁平化树（根据展开状态集合），用于列表与图谱
 */
export function flattenTree(nodes, expandedSet, depth = 0) {
    const result = [];
    for (const node of nodes) {
        result.push({ ...node, depth });
        if (expandedSet.has(node.entry.uid) && node.children.length > 0) {
            result.push(...flattenTree(node.children, expandedSet, depth + 1));
        }
    }
    return result;
}
/**
 * 全量扁平化（不管展开状态），用于 minimap
 */
export function flattenTreeAll(nodes, depth = 0) {
    const result = [];
    for (const node of nodes) {
        result.push({ ...node, depth });
        if (node.children.length > 0) {
            result.push(...flattenTreeAll(node.children, depth + 1));
        }
    }
    return result;
}
